	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/email-verification/verify", wrapper.VerifyEmail)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/email-verification/resend", wrapper.ResendEmailVerification)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/email-verification/resend-for-login", wrapper.ResendEmailVerificationForLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/password/reset/request", wrapper.RequestPasswordReset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/password/reset/verify", wrapper.VerifyPasswordResetToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/password/reset", wrapper.ResetPassword)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/auth/oidc/authorize", wrapper.StartOidcAuthorization)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/auth/oidc/callback", wrapper.HandleOidcCallback)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/users/me", wrapper.DeleteUser)
